def rule_pick(width_cm):
    if width_cm < 20:
        return "작은 집게"
    elif width_cm < 40:
        return "중간 집게"
    return "흡착컵"

for w in [15, 30, 55]:
    print(w, rule_pick(w))

demos = [(12, "작은 집게"), (18, "작은 집게"),
         (33, "중간 집게"), (52, "흡착컵")]

def learned_pick(w):
    best = demos[0]
    for d in demos:
        if abs(d[0] - w) < abs(best[0] - w):
            best = d
    return best[1]

print(learned_pick(25), learned_pick(45))

def policy(obs):
    hand_x, box_x = obs[0], obs[1]
    gap = box_x - hand_x
    if gap > 0:
        return "오른쪽"
    elif gap < 0:
        return "왼쪽"
    return "집기"

print(policy([2, 5]))
print(policy([4, 4]))

class LineWorld:
    def reset(self):
        self.pos, self.t = 0, 0
        return self.pos
    def step(self, action):
        self.pos = max(0, self.pos + action)
        self.t += 1
        reward = 10 if self.pos == 4 else -1
        done = self.pos == 4 or self.t >= 10
        return self.pos, reward, done

